    for c in range(cols):
        count = sum(1 for r in range(rows) if grid[r][c] == line_val)
        if count > rows * 0.6:
            v_lines.append(c)

    # Determine cell blocks (regions between grid lines)
    # For each 0-cell, check if it's adjacent (via broken walls) to another block
    # Actually, let's do flood fill on 0-cells to find connected components

    visited = [[False]*cols for _ in range(rows)]
    components = [[0]*cols for _ in range(rows)]
    comp_id = 0
    comp_cells = {}

    from collections import deque
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                comp_id += 1
                q = deque([(r,c)])
                visited[r][c] = True
                cells = []
                while q:
                    cr, cc = q.popleft()
                    components[cr][cc] = comp_id
                    cells.append((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and grid[nr][nc]==0:
                            visited[nr][nc] = True
                            q.append((nr,nc))
                comp_cells[comp_id] = cells

    # Find which components touch the border of the grid
    border_comps = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r==0 or r==rows-1 or c==0 or c==cols-1):
                border_comps.add(components[r][c])

    # Components that touch border AND have no broken walls = color 3
    # Components that have broken walls or are interior = color 4
    # Actually from examples: border components with intact walls = 3, others = 4
    # Let me reconsider: large connected regions (merged through broken walls) = 4, 
    # small normal cells on border = 3

    # Compute expected cell size (area between grid lines)
    # Normal cells have a standard size. Merged cells are larger.

    # Estimate standard cell size
    h_gaps = []
    prev = -1
    for h in sorted(h_lines):
        if prev >= 0:
            h_gaps.append(h - prev - 1)
        prev = h
    v_gaps = []
    prev = -1
    for v in sorted(v_lines):
        if prev >= 0:
            v_gaps.append(v - prev - 1)
        prev = v

    if h_gaps and v_gaps:
        from statistics import mode
        std_h = mode(h_gaps) if h_gaps else 4
        std_v = mode(v_gaps) if v_gaps else 4
        std_size = std_h * std_v
    else:
        std_size = 16

    # Components larger than standard = 4 (broken walls), check border for 3
    result = [row[:] for row in grid]
    for cid, cells in comp_cells.items():
        size = len(cells)
        if size <= std_size and cid in border_comps:
            color = 3
        else:
            color = 4
        for r,c in cells:
            result[r][c] = color

    return result

